import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

export const skills = [
  { ana: 86, ben: 64, skill: "Speed" },
  { ana: 58, ben: 88, skill: "Strength" },
  { ana: 74, ben: 70, skill: "Stamina" },
  { ana: 92, ben: 55, skill: "Agility" },
  { ana: 66, ben: 80, skill: "Defense" },
  { ana: 80, ben: 72, skill: "Vision" },
];

export const players = [
  { key: "ana", label: "Ana" },
  { key: "ben", label: "Ben" },
] as const;

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { RadarChart } from "@/registry/erbium/charts/radar-chart";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



const meta = {
  component: RadarChart,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nPass one row per axis, with one numeric field per series. Set `max` when several radar charts should be compared, so their outer rings mean the same value.\n\n```tsx\nimport { RadarChart } from \"@/registry/erbium/charts/radar-chart\";\n\n<RadarChart ariaLabel=\"Skills by player\" data={skills} index=\"skill\" series={players} max={100} />;\n```\n\nRadar charts need axes on the same scale. With fewer than five axes, or axes in different units, use a [Bar Chart](/docs/charts/bar-chart).",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof RadarChart>;

export default { ...meta, title: "Charts/Radar Chart",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

export const Playground: StoryObj<{
  legend: boolean;
  points: boolean;
  rings: number;
  tooltip: boolean;
}> = {
  argTypes: {
    legend: { control: "boolean" },
    points: { control: "boolean" },
    rings: { control: { max: 8, min: 2, type: "number" } },
    tooltip: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { RadarChart } from \"@/registry/erbium/charts/radar-chart\";\nimport { players, skills } from \"../examples/data\";\n\nexport const defaultProps = {\n  legend: true,\n  points: false,\n  rings: 4,\n  tooltip: true,\n} satisfies { legend: boolean; points: boolean; rings: number; tooltip: boolean };\n\nexport default function RadarChartPlaygroundExample(\n  args: { legend: boolean; points: boolean; rings: number; tooltip: boolean } = defaultProps,\n) {\n  return (\n    <div className=\"w-md max-w-full p-4\">\n      <RadarChart\n        ariaLabel=\"Skill ratings for two players\"\n        data={skills}\n        index=\"skill\"\n        series={players}\n        max={100}\n        initialWidth={400}\n        {...args}\n      />\n    </div>\n  );\n}\n" },
    },
  },
  render: PlaygroundExample,
};

import { RadarChart } from "@/registry/erbium/charts/radar-chart";
import { players, skills } from "../examples/data";

export const defaultProps = {
  legend: true,
  points: false,
  rings: 4,
  tooltip: true,
} satisfies { legend: boolean; points: boolean; rings: number; tooltip: boolean };

export default function RadarChartPlaygroundExample(
  args: { legend: boolean; points: boolean; rings: number; tooltip: boolean } = defaultProps,
) {
  return (
    <div className="w-md max-w-full p-4">
      <RadarChart
        ariaLabel="Skill ratings for two players"
        data={skills}
        index="skill"
        series={players}
        max={100}
        initialWidth={400}
        {...args}
      />
    </div>
  );
}
